<?php use CmuLms\View; $title='Teacher gradebook'; include __DIR__.'/../layout/header.php'; ?><section class="hero"><h1>Gradebook</h1><p>Scores for your courses and enrolled students.</p></section><section class="card"><div style="overflow-x:auto"><table><tr><th>Course</th><th>Student</th><th>School ID</th><th>Assessment</th><th>Category</th><th>Score</th><th>Released</th></tr><?php foreach($grades as $grade): ?><tr><td><?=View::e($grade['course_code'])?></td><td><?=View::e($grade['name'])?></td><td><?=View::e($grade['id_number'])?></td><td><?=View::e($grade['title'])?></td><td><?=View::e($grade['category'])?></td><td><?=View::e($grade['score'])?> / <?=View::e($grade['max_score'])?></td><td><?=!empty($grade['released'])?'Yes':'No'?></td></tr><?php endforeach; ?><?php if(!$grades): ?><tr><td colspan="7">No grades have been recorded yet.</td></tr><?php endif; ?></table></div></section><?php include __DIR__.'/../layout/footer.php'; ?>
